<?php
require_once __DIR__ . '/config.php';
$pageTitle='My day plan'; $active='planner';
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='reorder') {
  verify_csrf(); $submitted=array_values(array_unique(array_filter(array_map('intval',explode(',',(string)($_POST['order']??''))))));
  $current=array_map('intval',$_SESSION['plan']??[]); if(count($submitted)===count($current)&&!array_diff($submitted,$current)) $_SESSION['plan']=$submitted;
  flash('Your visit order has been saved.'); header('Location: planner.php'); exit;
}
$ids=array_map('intval',$_SESSION['plan']??[]); $places=[];
if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$q=db()->prepare("SELECT p.*,c.name category FROM places p JOIN categories c ON c.id=p.category_id WHERE p.id IN ($marks)");$q->execute($ids);$byId=[];foreach($q->fetchAll() as $p)$byId[(int)$p['id']]=$p;foreach($ids as $id)if(isset($byId[$id]))$places[]=$byId[$id];}
require __DIR__.'/includes/header.php';
?>
<section class="planner-hero"><div class="eyebrow">YOUR DAY, YOUR WAY</div><h1>Make a day of <em>it.</em></h1><p>Collect a few local places, then arrange them in the order that feels right.</p><div class="planner-summary"><span class="summary-number"><?= count($places) ?></span><span>place<?= count($places)===1?'':'s' ?> picked</span><i></i><span><?= array_sum(array_map(fn($p)=>(int)$p['visit_minutes'],$places)) ?> min of exploring</span></div></section>
<section class="section planner-content"><div class="section-heading compact"><div><div class="eyebrow eyebrow-dark">YOUR ITINERARY</div><h2>A simple plan for today</h2></div><a class="text-link" href="index.php#places">＋ Add another place</a></div>
<?php if(!$places): ?><div class="empty-state planner-empty"><div class="empty-icon">✳</div><h3>Your day is still wide open.</h3><p>Start by exploring places around Gampola and add the ones that catch your eye.</p><a class="button button-dark" href="index.php#places">Explore local places <span>→</span></a></div><?php else: ?>
<form id="reorder-form" method="post" class="reorder-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="reorder"><input type="hidden" id="plan-order" name="order" value="<?= e(implode(',',array_map(fn($p)=>(int)$p['id'],$places))) ?>"><button class="button button-dark" type="submit">Save my order</button></form><ol class="plan-list" data-reorder><?php foreach($places as $i=>$p): ?><li class="plan-item" draggable="true" data-id="<?= (int)$p['id'] ?>"><span class="drag-handle" title="Drag to reorder">⠿</span><span class="plan-number"><?= str_pad((string)($i+1),2,'0',STR_PAD_LEFT) ?></span><div class="plan-place"><span class="category-pill"><?= e($p['category']) ?></span><h3><a href="place.php?id=<?= (int)$p['id'] ?>"><?= e($p['name']) ?></a></h3><p><?= e($p['short_description']) ?></p></div><span class="plan-distance">⌖ <?= number_format((float)$p['distance_km'],1) ?> km</span><span class="plan-duration">◷ <?= (int)$p['visit_minutes'] ?> min</span><form method="post" action="plan_action.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="place_id" value="<?= (int)$p['id'] ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="return" value="planner.php"><button class="remove-plan" aria-label="Remove <?= e($p['name']) ?>">×</button></form></li><?php endforeach; ?></ol><div class="plan-footer"><span>Drag a place to change your visiting order.</span><span>Travel time between places is not included.</span></div><?php endif; ?></section>
<script>document.getElementById('reorder-form')?.addEventListener('submit',()=>{document.getElementById('plan-order').value=[...document.querySelectorAll('.plan-item')].map(item=>item.dataset.id).join(',')});</script>
<?php require __DIR__.'/includes/footer.php'; ?>
